            if ((((fields.len == 2) and std.mem.eql(u8, (if (@typeInfo(@TypeOf(fields[0])) == .@"enum" or @typeInfo(@TypeOf(fields[0])) == .@"union") @tagName(fields[0]) else fields[0].name), "items")) and std.mem.eql(u8, (if (@typeInfo(@TypeOf(fields[1])) == .@"enum" or @typeInfo(@TypeOf(fields[1])) == .@"union") @tagName(fields[1]) else fields[1].name), "capacity"))) {
                return ListContainerInfo{ .list = .array_list, .child = std.meta.Child(fields[0].type) };
            }
            if (@hasDecl(T, "looksLikeContainerTypeBabyList")) {
                return ListContainerInfo{ .list = .baby_list, .child = T.looksLikeContainerTypeBabyList };
            }
            if (@hasDecl(T, "looksLikeContainerTypeSmallList")) {
                return ListContainerInfo{ .list = .small_list, .child = T.looksLikeContainerTypeSmallList };
            }
        }
        return null;
}

pub fn Tagged(comptime U: type, comptime T: type) type {
        var info: std.builtin.Type.Union = @typeInfo(U).@"union";
        _ = &info;
        info.tag_type = T;
        info.decls = empty_decls[0..];
        info.layout = .auto;
        return @Type(std.builtin.Type{ .@"union" = info });
}

pub fn SliceChild(comptime T: type) type {
        const tyinfo = @typeInfo(T);
        if (((tyinfo == .pointer) and (tyinfo.pointer.size == .slice))) {
            return tyinfo.pointer.child;
        }
        return T;
}

pub fn useAllFields(comptime T: type, unused: VoidFields(T)) void {
        _ = unused;
}

pub fn VoidFields(comptime T: type) type {
        const fields = @typeInfo(T).@"struct".fields;
        var new_fields = (blk: {
        break :blk (fields[0..fields.len]).*;

});
        _ = &new_fields;
        for (cp_mut_slice(&new_fields)) |*field| {
            _ = &field;
            (field.*).type = void;
            (field.*).default_value_ptr = null;
        }
        return @Type(std.builtin.Type{ .@"struct" = std.builtin.Type.Struct{ .layout = .auto, .fields = new_fields[0..], .decls = empty_decls[0..], .is_tuple = false } });
}

pub fn voidFieldTypeDiscardHelper(data: anytype) void {
        _ = data;
}

pub fn hasDecl(comptime T: type, comptime name: []const u8) bool {
        return (switch (@typeInfo(T)) {
.@"struct", .@"union", .@"enum", .@"opaque" => @hasDecl(T, name),
else => false,
});
}

pub fn hasField(comptime T: type, comptime name: []const u8) bool {
        return (switch (@typeInfo(T)) {
.@"struct", .@"union", .@"enum" => @hasField(T, name),
else => false,
});
}
